using AutoMapper; using MediatR; using SMIS.Application.Common.Response; using SMIS.Application.DTO.ProductUnits; using SMIS.Application.Identity.IServices; using SMIS.Application.Repositories.ProductUnits; using SMIS.Domain.Services;
namespace SMIS.Application.Features.ProductUnits.Queries;
public record ProductUnitPullQuery(DateTime ChangedSince) : IRequest<Result<List<ProductUnitDto>>>;
internal sealed class ProductUnitPullQueryHandler : IRequestHandler<ProductUnitPullQuery,Result<List<ProductUnitDto>>>{private readonly IProductUnitRepository _repository;private readonly ICurrentUser _user;private readonly IMapper _mapper;public ProductUnitPullQueryHandler(IProductUnitRepository repository,ICurrentUser user,IMapper mapper)=>(_repository,_user,_mapper)=(repository,user,mapper);public async Task<Result<List<ProductUnitDto>>> Handle(ProductUnitPullQuery r,CancellationToken ct){var since=DateTimeService.NormalizeUtc(r.ChangedSince);var shopId=_user.GetShopId();var admin=_user.IsSuperAdmin();var items=await _repository.GetAllAsync(p=>p.LastModifiedUtc>since&&(admin||p.Product.ShopId==shopId),includeProperties:"Product",ignoreQueryFilters:true);return Result<List<ProductUnitDto>>.SuccessResult(_mapper.Map<List<ProductUnitDto>>(items));}}
